3	
4	import { defaultTeamPlayerList } from '@/tests/mocks/data/teamPlayer';
5	
6	import { Team } from './Team';
7	
8	const meta = {
9	    title: 'Player/Team',
10	    component: Team,
11	    parameters: {
12	        layout: 'centered',
13	    },
14	    tags: ['autodocs'],
15	} satisfies Meta<typeof Team>;
16	
17	export default meta;
18	type Story = StoryObj<typeof meta>;
19	
20	export const Primary: Story = {
21	    args: {
22	        teamName: 'B',
23	        team: defaultTeamPlayerList,
24	        maxTeamSize: defaultTeamPlayerList.length,
25	    },
26	    play: async ({ canvas }) => {
27	        // Each PlayerMugshot's <img> is aria-busy until ImageWithPlaceholder's
28	        // load/error handler fires — wait on that explicit signal for every
29	        // image rather than the CSS opacity it also drives, which depends on
30	        // transition timing and getComputedStyle semantics. The 10s budget
31	        // isn't about that ambiguity though: it's real headroom for when the
32	        // whole Storybook suite runs and dozens of images across other
33	        // stories are decoding under CPU contention at the same time (see
34	        // testTimeout in vitest.config.ts, which must exceed this).
35	        const total = (await canvas.findAllByRole('img', { name: /gary player/i })).length;
