            {/* <PlayerForm form={teamPlayer.form} /> */}
            {/* {teamPlayer.outcome.goalie ? <GoalieIndicator /> : null} */}
        </Card.Section>
    </Card>
);

import type { Meta, StoryObj } from '@storybook/nextjs-vite';
import { expect, waitFor } from 'storybook/test';

import { defaultTeamPlayerList } from '@/tests/mocks/data/teamPlayer';

import { Team } from './Team';

const meta = {
    title: 'Player/Team',
    component: Team,
    parameters: {
        layout: 'centered',
    },
    tags: ['autodocs'],
} satisfies Meta<typeof Team>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Primary: Story = {
    args: {
        teamName: 'B',
        team: defaultTeamPlayerList,
        maxTeamSize: defaultTeamPlayerList.length,
    },
    play: async ({ canvas }) => {
        // Each PlayerMugshot's <img> is aria-busy until ImageWithPlaceholder's
        // load/error handler fires — wait on that explicit signal for every
        // image rather than the CSS opacity it also drives, which depends on
        // transition timing and getComputedStyle semantics. The 10s budget
        // isn't about that ambiguity though: it's real headroom for when the
        // whole Storybook suite runs and dozens of images across other
        // stories are decoding under CPU contention at the same time (see
        // testTimeout in vitest.config.ts, which must exceed this).
        const total = (await canvas.findAllByRole('img', { name: /gary player/i })).length;
        await waitFor(() => {
            const ready = canvas.getAllByRole('img', { name: /gary player/i, busy: false });
            return expect(ready).toHaveLength(total);
        }, { timeout: 10000 });
    },
};

'use client';

import {
    Badge,
    Flex,
    Group,
    Paper,
    SimpleGrid,
    Text,
    Title,
} from '@mantine/core';

import { TeamPlayer } from '@/components/TeamPlayer/TeamPlayer';
import type { TeamResultState } from '@/lib/gameResult';
import { TeamPlayerType } from '@/types';

export interface Props {
    team: TeamPlayerType[];
    teamName: 'A' | 'B';
    maxTeamSize: number;
    result?: TeamResultState;
    hasBibs?: boolean;
}

const resultStyles: Record<TeamResultState, { label: string; color: string; }> = {
    win: { label: 'Won', color: 'teal' },
    loss: { label: 'Lost', color: 'red' },
    draw: { label: 'Draw', color: 'yellow' },
    unset: { label: 'Result unset', color: 'gray' },
};

export const Team = ({
    team,
    teamName,
    result = 'unset',
    hasBibs = false,
    maxTeamSize,
}: Props) => {
    return (
        <Paper p="md">
            <Flex
                direction={{ base: 'column', md: 'row' }}
                justify="space-between"
                gap="xs"
                p={0}
                mb="md"
                mt={0}
            >
                <Title order={3} fw={700}>Team {teamName}</Title>
                <Group gap="xs">
                    {hasBibs ? <Badge color="orange">Bibs</Badge> : null}
                    <Badge color={resultStyles[result].color}>
                        {resultStyles[result].label}
                    </Badge>
                </Group>
            </Flex>
            {
                team.length > 0 ?
                    (
                        <SimpleGrid
                            cols={{ base: 1, lg: 4, xl: Math.max(4, maxTeamSize) }}
                            spacing={{ base: 'xs', lg: 'sm' }}
                        >
                            {team.map((p) => (
                                <TeamPlayer
                                    key={p.id}
                                    teamPlayer={p}
                                />
                            ))}
                        </SimpleGrid>
                    ) :
                    <Text c="dimmed">No players selected.</Text>
            }
        </Paper>
    );
};

