for f in $FILES; do
  echo "--- $f ---"
  # Remove the standalone import specifier lines
  perl -ni -e 'print unless /^\s*Table(Tr|Td|Tbody|Th|Thead|ScrollContainer|Caption|Tfoot),\s*$/' "$f"
