    s/\bTableScrollContainer\b/Table.ScrollContainer/g;
    s/\bTableCaption\b/Table.Caption/g;
    s/\bTableTfoot\b/Table.Tfoot/g;
    s/\bTableTr\b/Table.Tr/g;
    s/\bTableTd\b/Table.Td/g;
    s/\bTableTh\b/Table.Th/g;
  ' "$f"
  git diff --stat -- "$f"
done

