30	import { IconAlertTriangle, IconCheck, IconChevronDown } from '@tabler/icons-react';
31	import { PlayerResponse } from 'prisma/generated/enums';
32	import { useEffect, useMemo, useRef, useState } from 'react';
33	
34	import { config } from '@/lib/config';
35	import { SubmitResponseProxy } from '@/types/actions/SubmitResponse';
36	import { OutcomePlayerType } from '@/types/OutcomePlayerType';
37	
38	interface ResponsesFormProps {
39	    gameId: number;
40	    gameDate: string;
41	    responses: OutcomePlayerType[];
42	    submitResponse: SubmitResponseProxy;
43	}
44	
45	type ResponseOption = PlayerResponse | 'None';
46	const ResponseOption = {
47	    ...PlayerResponse,
48	    None: 'None' as const,
49	};
50	
51	type ResponseValues = Pick<OutcomePlayerType, 'response' | 'goalie' | 'comment'>;
52	interface ResponsesFormValues {
53	    byPlayerId: Record<number, ResponseValues>;
54	}
55	
56	const toResponseValues = (row: OutcomePlayerType): ResponseValues => ({
57	    response: row.response ?? null,
58	    goalie: !!row.goalie,
59	    // v8 ignore next -- comment is always a string in practice (Prisma default '')
60	    comment: row.comment ?? '',
61	});
62	
63	const responseGroupBarColor: Record<ResponseOption, MantineColor> = {
64	    [ResponseOption.Yes]: 'green.6',
65	    [ResponseOption.No]: 'red.6',
66	    [ResponseOption.Dunno]: 'yellow.6',
67	    [ResponseOption.Excused]: 'gray.6',
68	    [ResponseOption.Flaked]: 'gray.6',
69	    [ResponseOption.Injured]: 'gray.6',
70	    [ResponseOption.None]: 'gray.6',
71	};
72	
73	export const ResponsesForm = ({
74	    gameId,
75	    gameDate,
76	    responses,
77	    submitResponse,
78	}: ResponsesFormProps) => {
79	    const form = useForm<ResponsesFormValues>({
80	        initialValues: {
81	            byPlayerId: Object.fromEntries(responses.map((row) => [row.playerId, toResponseValues(row)])),
82	        },
83	    });
84	    const [savingId, setSavingId] = useState<number | null>(null);
85	    const [filter, setFilter] = useState('');
86	    const [expandedGroups, setExpandedGroups] = useState<Set<ResponseOption>>(new Set());
87	    const isFiltering = filter.trim().length > 0;
88	
89	    const toggleGroup = (title: ResponseOption) => {
90	        setExpandedGroups((prev) => {
91	            const next = new Set(prev);
92	            if (next.has(title)) {
93	                next.delete(title);
94	            } else {
95	                next.add(title);
96	            }
97	            return next;
98	        });
99	    };
100	
101	    // Re-sync form values when the responses prop changes (e.g. after
102	    // revalidate / SSE refresh). Preserve any in-progress edits by only
103	    // overwriting rows whose form values still match the previous baseline.
104	    const prevResponsesRef = useRef(responses);
105	    useEffect(() => {
106	        const prevBaselineById = new Map(
107	            prevResponsesRef.current.map((row) => [row.playerId, toResponseValues(row)]),
108	        );
109	        for (const row of responses) {
110	            const newBaseline = toResponseValues(row);
111	            const oldBaseline = prevBaselineById.get(row.playerId) ?? newBaseline;
