}) | (MenuItemProps & {
    component: React.ElementType;
    renderRoot?: (props: Record<string, any>) => any;
})>, never> & import("../../..").ThemeExtend<{
    props: MenuItemProps;
    defaultRef: HTMLButtonElement;
