            autoClose: false,
            withCloseButton: false,
        });

        try {
            const response = await fetch('/api/auth/admin/stop-impersonating', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: '{}',
            });
            await assertOkResponse(response, {
                method: 'POST',
                fallbackMessage: 'Stop impersonation failed',
            });
