                id,
                color: 'teal',
                title: 'Impersonation ended',
                message: 'Back to your account.',
                icon: <IconCheck size={config.notificationIconSize} />,
                loading: false,
                autoClose: config.notificationAutoClose,
            });
        } catch (error) {
            const message = toPublicMessage(error, 'Stop impersonation failed');
            notifications.update({
                id,
                color: 'red',
                title: 'Error',
                message,
                icon: <IconAlertTriangle size={config.notificationIconSize} />,
                loading: false,
                autoClose: config.notificationAutoClose,
            });
        }
    }

    let name = 'Sign In';
    let email = '';
    let playerId = 0;

    if (user) {
        name = user.name ?? '';
        email = user.email ?? '';
        playerId = user.playerId;
    }

    const userMenu = user ? (
        <Menu.Dropdown>
            <Menu.Label>Account</Menu.Label>
            <Menu.Item leftSection={<IconUserScan size={14} />}>
                <Link className={classes.link} href="/footy/profile">
                    My Profile
                </Link>
            </Menu.Item>
            <Menu.Item leftSection={<IconPassword size={14} />}>
                <Link className={classes.link} href="/footy/password">
                    Change Password
                </Link>
